```c
#include <stdio.h>
#include <string.h>

int main() {
    // Define the source string and destination buffer
    char source[] = "Hello";
    char buffer[20];  // Ensure the buffer is large enough to hold the source string plus a null terminator

    // Copy the string from source to buffer
    memcpy(buffer, source, strlen(source) + 1);  // Add 1 for the null terminator

    // Print the destination buffer to verify the copy
    printf("Copied string: %s\n", buffer);

    return 0;
}
```

### Explanation:
