    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    int size, index, value;

    // Read the size of the array from standard input
    printf("Enter the size of the array: ");
    if (scanf("%d", &size) != 1) {
        fprintf(stderr, "Invalid input for array size\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for the array
    int *arr = (int *)malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Read the elements of the array from standard input
    printf("Enter %d elements:\n", size);
    for (int i = 0; i < size; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input for element at index %d\n", i);
            free(arr);
            return EXIT_FAILURE;
        }
    }

    // Read the index from standard input
    printf("Enter the index to retrieve: ");
    if (scanf("%d", &index) != 1) {
        fprintf(stderr, "Invalid input for index\n");
        free(arr);
        return EXIT_FAILURE;
    }

    // Get the value at the given index and print it
    value = getValueFromArray(arr, size, index);
    printf("Value at index %d is: %d\n", index, value);

    // Free the allocated memory
    free(arr);

    // Return the exit code
    return abs(value);  // Use absolute value to ensure a non-negative exit code
}
```

### Explanation:
