Here's the complete code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Function to print formatted string into dynamically allocated memory
char* print(const char* format, ...) {
    va_list args;
    va_start(args, format);

    // First call with NULL to get the size of the buffer needed
    int size = vsnprintf(NULL, 0, format, args) + 1;
    if (size <= 0) {
        va_end(args);
        return NULL; // Return NULL on error
    }

    // Allocate memory for the string
    char* str = (char*)malloc(size * sizeof(char));
    if (!str) {
        va_end(args);
        return NULL; // Return NULL if malloc fails
    }

    // Second call to actually format the string into the allocated buffer
    vsnprintf(str, size, format, args);

    va_end(args);
    return str;
}

// Function to execute a command as a system command
void execute_command(const char* command) {
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Failed to execute command.\n");
    } else if (WIFEXITED(status)) {
        printf("Command exited with status %d\n", WEXITSTATUS(status));
    }
}

int main() {
    const char* directory = "/home/user";
    char* command = print("ls -l %s", directory);

    if (!command) {
        fprintf(stderr, "Failed to create command string.\n");
        return 1;
    }

    execute_command(command);

    // Free the allocated memory
    free(command);

    return 0;
}
```

### Explanation:

1. **`print` Function**:
