    // Concatenate the strings
    char result[150]; // Ensure enough space for concatenated string and null terminator
    snprintf(result, sizeof(result), "%s%s%s", str1, str2, str3);

    // Write the resulting string to a file
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
