```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to trim trailing whitespace from a string
void trim_whitespace(char *str) {
    if (!str || !*str)
        return;

    size_t len = strlen(str);
    char *end = str + len - 1;

    while (end > str && (*end == ' ' || *end == '\t' || *end == '\n'))
        end--;

    *(end + 1) = '\0';
}

int main(int argc, char *argv[]) {
    // First if statement checks to make sure that the user provided exactly one argument
    if (argc != 2) {
        fprintf(stderr, "Error: Please provide exactly one argument.\n");
        exit(1);
    }

    // Second line gets the argument from the command line and stores it in a variable called input
    char *input = argv[1];

    // Third line prints the argument
    printf("Original Argument: %s\n", input);

    // Fourth line trims the trailing whitespace from the argument
    trim_whitespace(input);

    // Fifth line prints the argument again
    printf("Argument After Trimming Whitespace: %s\n", input);

    // Sixth line exits the program
    exit(0);
}
```

### Explanation:
1. **Error Checking**: The first `if` statement checks if the number of arguments (`argc`) is exactly 2 (since the first argument is always the name of the executable). If not, it prints an error message and exits with a status code of 1.
